import Browserbase from '@browserbasehq/sdk';
import { chromium } from 'playwright-core';
import { parseTimelineJson, parseDomRecords } from './parse.mjs';

const TIMELINE_RE = /\/graphql\/[^/]+\/SearchTimeline/;
const NAV_TIMEOUT_MS = 45000;
const SETTLE_MS = 6000;

// X reads the session from cookies on both hosts; ct0 must also travel as the
// x-csrf-token header on the XHR, which the page's own client handles once the
// cookie is present.
function sessionCookies({ xAuthToken, xCsrfToken }) {
  return ['x.com', 'twitter.com'].flatMap((domain) => [
    { name: 'auth_token', value: xAuthToken, domain: `.${domain}`, path: '/', httpOnly: true, secure: true },
    { name: 'ct0', value: xCsrfToken, domain: `.${domain}`, path: '/', secure: true },
  ]);
}

async function detectLoginWall(page) {
  const url = page.url();
  if (/\/(i\/flow\/login|login)/.test(url)) return true;
  return (await page.locator('input[name="text"][autocomplete="username"]').count()) > 0;
}

// Best-effort release so a session isn't left running (and billing) when
// something downstream throws. Swallows its own failure so the original
// error is always what the caller sees.
async function releaseSession(bb, session, config) {
  try {
    await bb.sessions.update(session.id, { status: 'REQUEST_RELEASE', projectId: config.browserbaseProjectId });
  } catch {
    // Release is best-effort — a failure here must not mask the original error.
  }
}

// Runs inside the browser. Mirrors the record shape parseDomRecords expects.
function extractDomRecords() {
  return Array.from(document.querySelectorAll('article[data-testid="tweet"]')).map((article) => {
    const timeEl = article.querySelector('time[datetime]');
    const permalink = timeEl?.closest('a')?.getAttribute('href') ?? '';
    const handleEl = Array.from(article.querySelectorAll('[data-testid="User-Name"] span')).find(
      (el) => el.textContent.startsWith('@'),
    );
    return {
      permalink,
      handle: handleEl?.textContent ?? '',
      text: article.querySelector('[data-testid="tweetText"]')?.textContent ?? '',
      datetime: timeEl?.getAttribute('datetime') ?? null,
      // Link destinations, as X renders them: the anchor text of a link in the
      // tweet body, and of a link-preview card, both read as the display URL
      // ("entire.io/blog/…"). The href itself is always t.co and says nothing.
      links: Array.from(
        article.querySelectorAll('[data-testid="tweetText"] a, [data-testid="card.wrapper"] a'),
      ).map((a) => a.textContent ?? ''),
      hasReplyingTo: article.textContent.includes('Replying to'),
      // Heuristic, DOM-fallback path only — less reliable than the JSON
      // path's `is_quote_status` field. A genuine quoted tweet is rendered as
      // a nested clickable card, so its tweetText lives inside a [role="link"]
      // container. Counting tweetText nodes (the naive check) also fires on
      // "Translate post", which renders original + translated text as two
      // same-testid blocks with no quote involved.
      hasQuotedTweet: article.querySelector('[role="link"] [data-testid="tweetText"]') !== null,
    };
  });
}

export async function scrapeSearch(config) {
  const bb = new Browserbase({ apiKey: config.browserbaseApiKey });
  const session = await bb.sessions.create({ projectId: config.browserbaseProjectId });

  let browser;
  try {
    browser = await chromium.connectOverCDP(session.connectUrl);

    const context = browser.contexts()[0];
    if (!context) {
      throw new Error('scrapeSearch: Browserbase session returned no browser context to inject cookies into');
    }
    await context.addCookies(sessionCookies(config));
    const page = context.pages()[0] || (await context.newPage());

    // Collect every SearchTimeline response the page fires; the first request
    // usually lands before `load` resolves, so the listener goes on first.
    // Handler promises are tracked (not just fired) and awaited below —
    // Playwright does not await `response` listeners itself, so without this
    // a still-in-flight `response.json()` could lose a race against the
    // fixed settle wait, silently truncating `payloads` and yielding a
    // partial-but-plausible `source: 'json'` result.
    const payloads = [];
    const pending = [];
    page.on('response', (response) => {
      if (!TIMELINE_RE.test(response.url())) return;
      pending.push(
        response
          .json()
          .then((json) => payloads.push(json))
          .catch(() => {
            // Non-JSON or already-consumed body — the DOM fallback covers us.
          }),
      );
    });

    await page.goto(config.searchUrl, { waitUntil: 'domcontentloaded', timeout: NAV_TIMEOUT_MS });
    await page.waitForTimeout(SETTLE_MS);
    await Promise.all(pending);

    const loginWall = await detectLoginWall(page);

    const fromJson = payloads.flatMap((payload) => parseTimelineJson(payload));
    if (fromJson.length) {
      // Wall detection is scoped (per spec) to a login-wall redirect or a
      // zero-result timeline with the login form present. A JSON payload
      // with real tweets means the session is good, so surfacing the raw
      // `loginWall` value here would report a false wall on a healthy
      // watcher and trip its backoff/Slack alarm for nothing.
      return { source: 'json', tweets: fromJson, loginWall: false };
    }

    const records = await page.evaluate(extractDomRecords);
    const domTweets = parseDomRecords(records);
    // Same scoping as the JSON path just above: the wall check only means
    // anything when we came back with nothing, otherwise a real result on a
    // healthy session would falsely trip the backoff/Slack alarm.
    return { source: 'dom', tweets: domTweets, loginWall: domTweets.length === 0 && loginWall };
  } catch (err) {
    await releaseSession(bb, session, config);
    throw err;
  } finally {
    if (browser) {
      try {
        await browser.close();
      } catch {
        // A close that throws (a flaky remote CDP socket, typically) must
        // never replace a real result or a real error from the try block —
        // that's exactly what a throw from `finally` would do. It also means
        // the close can't be relied on to have released the Browserbase
        // session, so do it explicitly here instead.
        await releaseSession(bb, session, config);
      }
    }
  }
}
import { loadConfig, loadEnvFile, getProjectDir } from './config.mjs';
import { scrapeSearch } from './x-scrape.mjs';
import { filterAndClassify } from './filter.mjs';
import { triage, MUTED, PRIORITY } from './tier.mjs';
import { classify, createClient } from './classify.mjs';
import { planAnnouncements, summarizeChain, chainIdOf } from './chain.mjs';
import { printWarning } from './notify-terminal.mjs';

loadEnvFile(getProjectDir());

let config;
try {
  config = loadConfig();
} catch (err) {
  printWarning(err.message);
  process.exit(1);
}

const { mutedHandles, teamHandles } = config;
const { source, tweets } = await scrapeSearch(config);
const classified = filterAndClassify(tweets, config);
const client = createClient(config.anthropicApiKey);

console.log(
  `query=${config.searchQuery}\n` +
    `source=${source} tweets=${classified.length} ` +
    `muted=[${mutedHandles.join(',') || '-'}] team=[${teamHandles.join(',') || '-'}] ` +
    `classifier=${client ? 'on' : 'off'}\n`,
);

let calls = 0;
const rows = [];
for (const tweet of classified) {
  const pre = triage(tweet, { mutedHandles, teamHandles });
  let verdict = null;
  if (pre.tier !== MUTED && client) {
    verdict = await classify(tweet, { client });
    calls += 1;
    if (!verdict.ok) console.log(`  !! classify failed: ${verdict.error}`);
  }
  rows.push({ tweet, decision: triage(tweet, { mutedHandles, teamHandles, verdict }), verdict });
}

for (const { tweet, decision, verdict } of rows) {
  const mark = decision.tier === PRIORITY ? '*' : decision.tier === MUTED ? '-' : ' ';
  const llm = (verdict?.ok ? verdict.tier : 'n/a').padEnd(8);
  console.log(
    `${mark} ${decision.tier.padEnd(8)} score=${String(decision.score).padStart(2)} llm=${llm} ` +
      `@${tweet.author.padEnd(17)} via=${tweet.matchedVia.padEnd(6)} ` +
      `f=${String(tweet.followers ?? '?').padStart(6)} ` +
      tweet.text.replace(/\s+/g, ' ').slice(0, 56),
  );
  if (verdict?.ok && verdict.reason) console.log(`${' '.repeat(15)}${verdict.reason}`);
}

const counts = rows.reduce((acc, r) => ({ ...acc, [r.decision.tier]: (acc[r.decision.tier] || 0) + 1 }), {});
console.log(`\ntiers: ${JSON.stringify(counts)} | classifier calls: ${calls}`);

// What Slack would actually receive. The budget starts empty here: preview
// reads no store, so this is one poll on a quiet thread history, not what a
// running watcher would do mid-flood.
const plan = planAnnouncements(
  rows.filter((r) => r.decision.tier !== MUTED).map(({ tweet, decision }) => ({ tweet, decision })),
  { limit: config.chainLimit },
);

console.log(`\nslack lines: ${plan.length} (from ${rows.length} mentions, budget ${config.chainLimit}/thread)`);
for (const item of plan) {
  if (item.type === 'post') {
    console.log(
      `  ${item.decision.tier === PRIORITY ? '*' : ' '} @${item.tweet.author.padEnd(17)} ` +
        `${chainIdOf(item.tweet)}`,
    );
    continue;
  }
  const summary = summarizeChain(item.entries);
  console.log(
    `  + CHAIN ${summary.count} more in ${item.chainId} ` +
      `(${summary.authors.map((a) => `@${a}`).join(', ')}${summary.moreAuthors ? ` +${summary.moreAuthors}` : ''})`,
  );
}

console.log('Nothing was posted to Slack and no state was written.');
import test from 'node:test';
import assert from 'node:assert/strict';
import { scoreTweet, parseHandleList, PRIORITY_THRESHOLD } from '../scripts/score.mjs';
import { triage, decideTier, PRIORITY, ROUTINE, MUTED } from '../scripts/tier.mjs';
import { buildPrompt } from '../scripts/classify.mjs';

function tweet(over = {}) {
  return {
    id: '1', author: 'somedev', text: 'neat', url: 'https://x.com/somedev/status/1',
    createdAt: new Date().toISOString(), kind: 'reply',
    followers: 100, followsUs: true, verified: false, ...over,
  };
}

test('parseHandleList normalizes @ and case and drops blanks', () => {
  assert.deepEqual(parseHandleList('@Lizziepika, BlackGirlBytes ,, '), ['lizziepika', 'blackgirlbytes']);
});

test('parseHandleList on empty input is an empty list', () => {
  assert.deepEqual(parseHandleList(undefined), []);
  assert.deepEqual(parseHandleList(''), []);
});

test('a large account scores for reach', () => {
  assert.equal(scoreTweet(tweet({ followers: 17388 })).score, 3);
});

test('a non-follower scores for reach we do not already have', () => {
  const { score, reasons } = scoreTweet(tweet({ followsUs: false }));
  assert.equal(score, 2);
  assert.ok(reasons.includes('not a follower'));
});

test('an unknown follow relationship is not treated as a non-follower', () => {
  assert.equal(scoreTweet(tweet({ followsUs: null })).score, 0);
});

test('a question scores', () => {
  assert.ok(scoreTweet(tweet({ text: 'does this work with self-hosted runners?' })).score >= 2);
});

test('switching intent needs both a competitor and an intent verb', () => {
  assert.ok(scoreTweet(tweet({ text: 'migrating off github to entire' })).reasons.includes('switching intent'));
  assert.ok(!scoreTweet(tweet({ text: 'github is down again' })).reasons.includes('switching intent'));
});

test('a team account is scored down hard', () => {
  assert.ok(scoreTweet(tweet({ author: 'lizziepika', followers: 17388 }), { teamHandles: ['lizziepika'] }).score < 0);
});

test('a muted handle is muted before anything else runs', () => {
  const r = triage(tweet({ author: 'lizziepika' }), { mutedHandles: ['lizziepika'] });
  assert.equal(r.tier, MUTED);
});

test('muting is case and @ insensitive', () => {
  assert.equal(triage(tweet({ author: 'LizziePika' }), { mutedHandles: parseHandleList('@lizziepika') }).tier, MUTED);
});

test('a teammate reply is always routine, however high it scores', () => {
  const r = triage(
    tweet({ author: 'blackgirlbytes', followers: 50000, followsUs: false, text: 'how do I do X?' }),
    { teamHandles: ['blackgirlbytes'] },
  );
  assert.equal(r.tier, ROUTINE);
});

test('an LLM PRIORITY verdict promotes a low-scoring mention', () => {
  const r = triage(tweet({ followers: 80 }), { verdict: { ok: true, tier: 'PRIORITY', reason: 'support question' } });
  assert.equal(r.tier, PRIORITY);
  assert.ok(r.score < PRIORITY_THRESHOLD, 'precondition: score alone would not promote');
});

test('an LLM IGNORE verdict demotes a high-scoring mention', () => {
  const r = triage(
    tweet({ followers: 50000, followsUs: false, text: 'airdrop?' }),
    { verdict: { ok: true, tier: 'IGNORE', reason: 'crypto spam' } },
  );
  assert.equal(r.tier, ROUTINE);
});

test('IGNORE demotes but never drops, so a misfire stays visible', () => {
  const r = triage(tweet(), { verdict: { ok: true, tier: 'IGNORE', reason: 'spam' } });
  assert.notEqual(r.tier, MUTED);
});

test('a failed classifier falls back to the score, still promoting a strong mention', () => {
  const r = triage(
    tweet({ followers: 17388, followsUs: false, text: 'does entire support self-hosted runners?' }),
    { verdict: { ok: false, error: 'timeout' } },
  );
  assert.equal(r.tier, PRIORITY);
});

test('a failed classifier leaves a weak mention routine', () => {
  assert.equal(triage(tweet({ followers: 10 }), { verdict: { ok: false, error: 'timeout' } }).tier, ROUTINE);
});

test('no classifier at all behaves exactly like a failed one', () => {
  const strong = { followers: 17388, followsUs: false, text: 'how do I migrate from github?' };
  assert.equal(triage(tweet(strong), { verdict: null }).tier, triage(tweet(strong), { verdict: { ok: false } }).tier);
});

test('the LLM reason is carried into the displayed reasons', () => {
  const r = triage(tweet(), { verdict: { ok: true, tier: 'PRIORITY', reason: 'asks about pricing' } });
  assert.ok(r.reasons.includes('asks about pricing'));
});

test('decideTier does not mutate the reasons array it is given', () => {
  const reasons = ['question'];
  decideTier({ tweet: tweet(), score: 9, reasons, verdict: { ok: true, tier: 'PRIORITY', reason: 'x' } });
  assert.deepEqual(reasons, ['question']);
});

test('an explicit ROUTINE verdict is not overridden by a high score', () => {
  // Regression: reach alone promoted emoji tag-chain replies the classifier
  // had already judged routine.
  const r = triage(
    tweet({ author: 'someone', followers: 2292, followsUs: false, kind: 'mention' }),
    { verdict: { ok: true, tier: 'ROUTINE', reason: 'emoji-only tag reply' } },
  );
  assert.ok(r.score >= PRIORITY_THRESHOLD, 'precondition: score alone would promote');
  assert.equal(r.tier, ROUTINE);
});

test('a PRIORITY verdict still wins over a zero score', () => {
  const r = triage(
    tweet({ followers: 5, followsUs: true }),
    { verdict: { ok: true, tier: 'PRIORITY', reason: 'support question' } },
  );
  assert.equal(r.tier, PRIORITY);
});

test('the classifier is told how the mention matched', () => {
  // A link share is not addressed to us. Without this the model reads every
  // post as if the author tagged the account and expects an answer.
  assert.match(buildPrompt(tweet({ matchedVia: 'link' })), /^Matched: links the site/m);
  assert.match(buildPrompt(tweet({ matchedVia: 'both' })), /^Matched: tags the account and links/m);
  assert.match(buildPrompt(tweet({ matchedVia: 'handle' })), /^Matched: tags the account$/m);
  assert.match(buildPrompt(tweet()), /^Matched: tags the account$/m);
});

